import{_ as a,o as t,c as n,ae as o}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"ADR: Context Pack and Domain Binding","description":"","frontmatter":{},"headers":[],"relativePath":"adr/context-pack-domain-binding.md","filePath":"adr/context-pack-domain-binding.md"}'),i={name:"adr/context-pack-domain-binding.md"};function s(r,e,c,d,l,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-context-pack-and-domain-binding" tabindex="-1">ADR: Context Pack and Domain Binding <a class="header-anchor" href="#adr-context-pack-and-domain-binding" aria-label="Permalink to &quot;ADR: Context Pack and Domain Binding&quot;">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Accepted — 2026-06-22</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The metadata catalog POC demonstrated context graph concepts (lineage, policy, GenUI) with enterprise MAU fixtures. Product direction also requires a Taiwan agri/spice supply-chain narrative without embedding vertical domain knowledge in platform code.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Introduce a <strong>three-layer model</strong>:</p><ol><li><strong>Platform</strong> — domain-neutral contracts, services, routes, GenUI registry, OPA input shape, MCP/agent tools.</li><li><strong>Context packs</strong> — declarative JSON under <code>content/context-packs/&lt;pack-id&gt;/</code> (assets, metrics, glossary, bindings).</li><li><strong>Domain modules</strong> — optional features (e.g. food/recipe) referenced only via <code>bindings.json</code> opaque refs.</li></ol><p>Default pack: <code>enterprise-mau</code>. Second pack: <code>agri-supply</code>. UI pack switcher sets cookie + <code>?pack=</code> query.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Core TypeScript must not contain vertical product names; packs hold domain copy.</li><li><code>metadata-assets.json</code> remains as transitional mirror; SoT is pack <code>assets.json</code>.</li><li>Backend bindings API returns <code>resolved: false</code> when food seed entities are absent (Remix resolves when seeded).</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./stateless-mcp-genui-metadata.html">stateless-mcp-genui-metadata.md</a></li><li><a href="./../product/context-pack-model.html">docs/product/context-pack-model.md</a></li></ul>',13)])])}const h=a(i,[["render",s]]);export{u as __pageData,h as default};
